import{bV as e,aL as t,u as r,G as i}from"./chunks/framework.ByYcXNJx.js";const f=JSON.parse('{"title":"数学建模活动的经历","description":"数学建模活动的经历","frontmatter":{"title":"数学建模活动的经历","date":"2023-05-13T08:00:00.000Z","cover":"https://article.biliimg.com/bfs/article/f0cd20d62e6b2c2e6bd6153f410f81a5cae5003c.png","tags":["文章","LSTM","神经网络","高中"],"categories":["教育相关","技术笔记"],"description":"数学建模活动的经历","permalink":"/pages/2c1ed0"},"headers":[],"relativePath":"数学建模活动的经历.md","filePath":"数学建模活动的经历.md","lastUpdated":null}'),l={name:"数学建模活动的经历.md"};function o(p,a,s,c,n,d){return t(),r("div",null,[...a[0]||(a[0]=[i(`<h1 id="数学建模活动的经历" tabindex="-1">数学建模活动的经历 <a class="header-anchor" href="#数学建模活动的经历" aria-label="Permalink to &quot;数学建模活动的经历&quot;">​</a></h1> <h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2> <p>今年四月份（快五一的时候），我们学年数学组搞了一个数学建模的活动。然后我当时想到的就是深度学习之类的东西。所以我打算就一拍即合，报名了这次活动。</p> <h2 id="选题的筹备" tabindex="-1">选题的筹备 <a class="header-anchor" href="#选题的筹备" aria-label="Permalink to &quot;选题的筹备&quot;">​</a></h2> <p>老师说选题要与生活有关系。不过在五一时期的话。我脑海里能想到的第一个关键词就是 游玩 。而众所周知，像五一这样的旅游旺季，肯定会有一个字离不开。 那就是 “堵车”。</p> <p>是的，基本上大部分的旅游时间都耽误在道上。看到的不是风景，而是熙熙攘攘的人群。而堵车这个因素又跟交通有关。所以我们打算做交通预测这个选题</p> <h2 id="技术选型" tabindex="-1">技术选型 <a class="header-anchor" href="#技术选型" aria-label="Permalink to &quot;技术选型&quot;">​</a></h2> <p>在这次建模中，我们选用了LSTM网络去针对交通拥堵的建模。LSTM有天然的时序数据处理优势。</p> <p>我曾经在AI Studio上看到用LSTM预测股价的案例。因为股票价格的涨或跌可以简单看作是由时间这个序列引起的。而我们的交通拥堵情况也可以简单看作一个时间序列引起的。所以我想把LSTM网络迁移到这里来。</p> <h2 id="过程" tabindex="-1">过程 <a class="header-anchor" href="#过程" aria-label="Permalink to &quot;过程&quot;">​</a></h2> <h3 id="数据集的准备-预处理" tabindex="-1">数据集的准备&amp;预处理 <a class="header-anchor" href="#数据集的准备-预处理" aria-label="Permalink to &quot;数据集的准备&amp;预处理&quot;">​</a></h3> <p>要搭建模型肯定是得有数据集做支撑的。我们当时正好在arxiv上搜到了一篇论文</p> <p><a href="https://doi.org/10.48550/arXiv.2203.06213" target="_blank" rel="noreferrer">TrafPS: A Visual Analysis System Interpreting Traffic Prediction in Shapley -arXiv:2203.06213</a></p> <p>这篇论文做的跟交通预测有关，选取的数据集是由滴滴数据开放平台提供的路况数据。不过因为时间已久，这个开放平台已经不再提供数据。然后我们在GitHub上搜BaiduTraffic（主要是百度的数据还是比较准的），结果还真的搜到了数据集。但是，还得从百度网盘下载。众所周知，百度网盘的下载速度真是一言难尽。不过在发现这个数据集的同时。我们也发现了另外一个数据集，是<a href="https://tianchi.aliyun.com/competition/entrance/231598/introduction" target="_blank" rel="noreferrer">阿里天池云上贵州智慧交通预测挑战赛</a>的数据。这个下载速度还快，而且数据质量也很好。于是我就用它这个了。</p> <p>不过下下来的数据上是很多个因素导致一个路段堵不堵车的。比如上游路段的拥堵时长。在这里，为了方便建模。我们只选择一个路段进行建模。</p> <h3 id="lstm模型的理解" tabindex="-1">LSTM模型的理解 <a class="header-anchor" href="#lstm模型的理解" aria-label="Permalink to &quot;LSTM模型的理解&quot;">​</a></h3> <p>其实，当时只是知道应该选用LSTM网络来建模。但还不知道怎么样搭建。于是我就翻了很多很多的api文档。以及LSTM网络的原理。而且可能要解决很多的问题啊，比如h_n,c_n没有重置的问题。num_layers的问题等等。在不断的尝试下，终于把网络搭建好了</p> <h3 id="训练的准备" tabindex="-1">训练的准备 <a class="header-anchor" href="#训练的准备" aria-label="Permalink to &quot;训练的准备&quot;">​</a></h3> <p>我们用的是DatasetLoader去加载数据集，又把数据集分成了训练集，测试集，验证集。我们用的是SGD优化器去优化。然后用scheduler来去动态调节学习率，然后在训练的过程中还有保存点的设置。由于我们当时还没接触到tensorboard，所以loss图都是用matplotlib画的。</p> <h3 id="训练过程1" tabindex="-1">训练过程1 <a class="header-anchor" href="#训练过程1" aria-label="Permalink to &quot;训练过程1&quot;">​</a></h3> <p>第一次训练是在我朋友家进行的。用的是cpu去训练模型。总共跑完100step也就一个小时。不过loss实在是不如人意。而且训完之后情况非常糟糕</p> <p>（loss图是这样的）</p> <p><img src="https://article.biliimg.com/bfs/article/83f70fdf33773f63e266fd4753e694c2d55e0329.png" alt=""></p> <p>train_loss几乎都是平的。val_loss下降好半天也只是下到了10。</p> <p>于是我开始再看别人的博客什么的去改进自己的网络。我发现两个重要的原因。</p> <p>1.我当时选用的是SGD优化器，收敛速度较慢</p> <p>2.没进行归一化</p> <p>于是我就针对这两个问题进行修改。把SGD改成了Adam优化器。之后把数据用Min/Max 的方法去归一化。为了提升训练速度我用的是AutoDL的机子训练，用的是 2080Ti 显卡来推理（这样可以用CUDA加速）于是，第二次训练就开始了</p> <h3 id="第二次训练" tabindex="-1">第二次训练 <a class="header-anchor" href="#第二次训练" aria-label="Permalink to &quot;第二次训练&quot;">​</a></h3> <p>吸取上次的经验我几乎时时刻刻都看着loss图。不过可喜的是，训练没多久就收敛的很快。这简直真的震惊到我了。loss图如下</p> <p><img src="https://article.biliimg.com/bfs/article/a86f564fb726937f4efe94192cd389c305eabb5d.png" alt=""></p> <p>这回loss真的就是一泻千里。至少不会太像上次那么离谱。经过测试，模型还是表现的很良好的</p> <h3 id="预测与分析" tabindex="-1">预测与分析 <a class="header-anchor" href="#预测与分析" aria-label="Permalink to &quot;预测与分析&quot;">​</a></h3> <p>我们把前两秒的数据放进模型里面，预测后面的数据，比较符合实际情况（如下图）</p> <p><img src="https://article.biliimg.com/bfs/article/1ecd641a79caf7e21ae2aadb4d83968407836925.png" alt=""></p> <p>不过，我们还没有建立一个数学解析式（问我为啥？老师要求的QAQ）于是我们用geogebra去对预测数据拟合</p> <p><img src="https://article.biliimg.com/bfs/article/445a708e26152a5bc8f12ddce1c44da158412fd2.png" alt=""></p> <p><img src="https://article.biliimg.com/bfs/article/fd670a3e901044cb4865f76e5b8f10d3fde5a3fe.png" alt=""></p> <p><img src="https://article.biliimg.com/bfs/article/aaca1bdb44f955a8c1cfd16bf83f9d8418e88763.png" alt=""></p> <h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2> <p>这次的话是我对于LSTM网络的认识和初实践。我们队伍在这次比赛中获得特等奖（而且特等奖中还是第一名）。
那么就先到这里了，拜拜</p>`,81)])])}const b=e(l,[["render",o]]);export{f as __pageData,b as default};
